└── nuxt.config.ts     # Configuração do projeto
```

### 💻 Exemplo de Implementação

#### 1. Store de Autenticação (Pinia)

Este store gerenciará o estado de login e o token.

**`stores/authStore.js`**

```javascript
import { defineStore } from 'pinia';

export const useAuthStore = defineStore('auth', {
  state: () => ({
    token: localStorage.getItem('authToken') || null,
    isAuthenticated: !!localStorage.getItem('authToken'),
    user: null,
  }),
  actions: {
    async login(credentials) {
      try {
        // Use $fetch (nativo do Nuxt) para chamar a API NestJS
        const response = await $fetch('/api/auth/login', {
          method: 'POST',
          body: credentials,
        });

        const { access_token } = response;

        // Armazenar o token
        localStorage.setItem('authToken', access_token);
        this.token = access_token;
        this.isAuthenticated = true;

        // Opcional: Buscar o perfil após o login
        await this.fetchUserProfile(); 

        return response;
      } catch (error) {
        console.error("Erro no login:", error);
        throw error;
      }
    },

    async fetchUserProfile() {
      if (!this.token) return;
      try {
        // Incluir o token no header de autorização
        const response = await $fetch('/api/auth/profile', {
          headers: {
            Authorization: `Bearer ${this.token}`,
          },
        });
        this.user = response;
      } catch (error) {
        console.error("Erro ao buscar perfil:", error);
        this.logout(); // Se o token for inválido, deslogar
      }
    },

    logout() {
      localStorage.removeItem('authToken');
      this.token = null;
      this.isAuthenticated = false;
      this.user = null;
      // Redirecionar para a página de login
      navigateTo('/login');
    },
  },
});
```

